style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
#game-details-play-button-container .btn-play {
        background-color: #3399ff !important;
        border-radius: 12px !important;
        padding: 10px 20px !important;
        font-size: 16px !important;
        color: white !important;
        text-transform: uppercase !important;
        font-weight: bold !important;
        border: none !important;
        cursor: pointer !important;
        transition: background-color 0.3s ease, transform 0.2s ease;
    }

    #game-details-play-button-container .btn-play:hover {
        background-color: #0077e6 !important;
        transform: scale(1.05);
    }

    #game-details-play-button-container .btn-play:focus {
        outline: none !important;
        box-shadow: 0 0 0 3px rgba(51, 153, 255, 0.5) !important;
    }
}
